import React, { useState } from 'react';
import { motion } from 'framer-motion';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Simulating API call
    try {
      // Mock login - replace with actual API call
      await new Promise(resolve => setTimeout(resolve, 1500));
      console.log('Login attempt with:', formData);
      // Proceed with login logic
      
    } catch (err) {
      setError('Invalid login credentials. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="relative flex flex-col items-center justify-center min-h-screen p-4 overflow-hidden bg-neural-dark">
      {/* Neural background effect */}
      <div className="absolute inset-0 neural-network-bg">
        {Array.from({ length: 15 }).map((_, i) => (
          <motion.circle
            key={i}
            r={Math.random() * 3 + 1}
            fill="rgba(100, 200, 255, 0.3)"
            cx={`${Math.random() * 100}%`}
            cy={`${Math.random() * 100}%`}
            initial={{ opacity: 0.1 }}
            animate={{ 
              opacity: [0.1, 0.3, 0.1],
              scale: [1, 1.2, 1],
            }}
            transition={{ 
              duration: Math.random() * 3 + 2,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      {/* Connection lines */}
      <svg className="absolute inset-0 w-full h-full neural-connection">
        {Array.from({ length: 10 }).map((_, i) => (
          <motion.path
            key={i}
            stroke="rgba(100, 200, 255, 0.15)"
            strokeWidth="1"
            fill="none"
            d={`M${Math.random() * 100},${Math.random() * 100} C${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100}`}
            initial={{ pathLength: 0, opacity: 0 }}
            animate={{ 
              pathLength: 1, 
              opacity: [0, 0.3, 0]
            }}
            transition={{ 
              duration: Math.random() * 4 + 3,
              repeat: Infinity,
              delay: Math.random() * 2
            }}
          />
        ))}
      </svg>

      {/* Login card */}
      <motion.div 
        className="neural-card w-full max-w-md p-6 z-10"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="text-center mb-8">
          <motion.h1 
            className="text-3xl font-bold neural-text-gradient"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.8 }}
          >
            Track Your Study
          </motion.h1>
          <motion.p 
            className="mt-2 text-white/70"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3, duration: 0.8 }}
          >
            Log in to your account
          </motion.p>
        </div>

        {error && (
          <motion.div 
            className="mb-4 p-3 bg-red-900/40 border border-red-500/30 rounded-lg text-red-300 text-sm"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
          >
            {error}
          </motion.div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="email" className="block mb-2 text-sm font-medium text-white/80">
              Email
            </label>
            <input
              type="email"
              id="email"
              name="email"
              className="neural-input w-full text-white/90"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>

          <div className="mb-6">
            <label htmlFor="password" className="block mb-2 text-sm font-medium text-white/80">
              Password
            </label>
            <input
              type="password"
              id="password"
              name="password"
              className="neural-input w-full text-white/90"
              placeholder="Enter your password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <input
                id="remember"
                type="checkbox"
                className="w-4 h-4 bg-gray-800 border-dendrite-base rounded focus:ring-dendrite-base"
              />
              <label htmlFor="remember" className="ml-2 text-sm text-white/70">
                Remember me
              </label>
            </div>
            <button type="button" className="text-sm text-neural-primary hover:text-neural-secondary transition-colors">
              Forgot password?
            </button>
          </div>

          <motion.button
            type="submit"
            className="neural-button w-full py-3 rounded-lg bg-dendrite-primary/20 border border-dendrite-base text-white font-medium"
            whileHover={{ scale: 1.02, boxShadow: '0 0 15px rgba(100, 200, 255, 0.5)' }}
            whileTap={{ scale: 0.98 }}
            disabled={isLoading}
          >
            {isLoading ? (
              <span className="flex items-center justify-center">
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Logging in...
              </span>
            ) : (
              'Log In'
            )}
          </motion.button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-white/60 text-sm">
            Don't have an account?{' '}
            <button type="button" className="text-neural-primary hover:text-neural-secondary transition-colors">
              Sign up
            </button>
          </p>
        </div>
      </motion.div>
    </div>
  );
};

export default Login; 